; nasm -f bin tests/bootsectors/acpi_button.asm -o tests/bootsectors/acpi_button.bin
; No firmware: program the PIC/ACPI registers, sleep, and service the actual
; IRQ9 event generated by the host's power-button input. The handler acks the
; event and enters S5. A mere halted CPU is not a powered-off machine.
bits 16
org 0x7c00
    cli
    xor ax, ax
    mov ds, ax
    mov ss, ax
    mov sp, 0x7c00
    lidt [idt]
    mov word [0x29 * 4], handler
    mov word [0x29 * 4 + 2], 0
    mov al, 0x11
    out 0x20, al
    out 0xa0, al
    mov al, 0x20
    out 0x21, al
    mov al, 0x28
    out 0xa1, al
    mov al, 4
    out 0x21, al
    mov al, 2
    out 0xa1, al
    mov al, 1
    out 0x21, al
    out 0xa1, al
    mov al, 0xfb
    out 0x21, al
    mov al, 0xfd
    out 0xa1, al
    mov al, 0xf1
    out 0xb2, al
    mov dx, 0x602
    mov ax, 0x100
    out dx, ax
    sti
    hlt
    jmp $
handler:
    mov dx, 0x600
    in ax, dx
    test ax, 0x100
    jz failed
    mov ax, 0x100
    out dx, ax
    in ax, dx
    test ax, 0x100
    jnz failed
    mov al, 0x20
    out 0xa0, al
    out 0x20, al
    mov al, 'P'
    mov dx, 0x3f8
    out dx, al
    mov dx, 0x604
    mov ax, 0x2000
    out dx, ax
failed:
    cli
    hlt
    jmp $
idt: dw 0x3ff
     dd 0
times 510-($-$$) db 0
dw 0xaa55
